begin;
create extension if not exists pgtap with schema extensions;
select plan(14);
select has_function('public','reassign_conversation_handoff','manager reassignment RPC exists');
insert into public.organizations(id,name,slug) values('a0000000-0000-0000-0000-000000000015','Support fixture','support-015-fixture');
insert into auth.users(id) values('b0000000-0000-4000-8000-000000000151'),('b0000000-0000-4000-8000-000000000152'),('b0000000-0000-4000-8000-000000000153'),('b0000000-0000-4000-8000-000000000154');
insert into public.staff_profiles(user_id,organization_id,role,active) values('b0000000-0000-4000-8000-000000000151','a0000000-0000-0000-0000-000000000001','staff',false),('b0000000-0000-4000-8000-000000000152','a0000000-0000-0000-0000-000000000001','staff',true),('b0000000-0000-4000-8000-000000000153','a0000000-0000-0000-0000-000000000001','manager',true),('b0000000-0000-4000-8000-000000000154','a0000000-0000-0000-0000-000000000015','staff',true);
insert into public.facebook_inbound_events(id,organization_id,page_id,provider_key,kind,sender_id,recipient_id,data) values('e0000000-0000-4000-8000-000000000151','a0000000-0000-0000-0000-000000000001','10000000015','support-reassign-fixture','message','20000000015','10000000015','{}');
insert into public.conversations(id,organization_id,page_id,psid) values('c0000000-0000-4000-8000-000000000151','a0000000-0000-0000-0000-000000000001','10000000015','20000000015');
insert into public.conversation_handoffs(id,conversation_id,source_event_id,reason,status,claimed_by,claimed_at) values('d0000000-0000-4000-8000-000000000151','c0000000-0000-4000-8000-000000000151','e0000000-0000-4000-8000-000000000151','customer_requested','STAFF_ACTIVE','b0000000-0000-4000-8000-000000000151','2026-01-01');
update public.conversations set status='STAFF_ACTIVE',revision=2,active_handoff_id='d0000000-0000-4000-8000-000000000151' where id='c0000000-0000-4000-8000-000000000151';
set local role service_role;
select throws_ok($$select public.reassign_conversation_handoff('a0000000-0000-0000-0000-000000000001','b0000000-0000-4000-8000-000000000152','c0000000-0000-4000-8000-000000000151',2,'b0000000-0000-4000-8000-000000000152',gen_random_uuid())$$,'42501','conversation_forbidden','staff cannot reassign');
select throws_ok($$select public.reassign_conversation_handoff('a0000000-0000-0000-0000-000000000001','b0000000-0000-4000-8000-000000000153','c0000000-0000-4000-8000-000000000151',2,'b0000000-0000-4000-8000-000000000151',gen_random_uuid())$$,'42501','conversation_forbidden','disabled assignee rejected');
select throws_ok($$select public.reassign_conversation_handoff('a0000000-0000-0000-0000-000000000001','b0000000-0000-4000-8000-000000000153','c0000000-0000-4000-8000-000000000151',2,'b0000000-0000-4000-8000-000000000154',gen_random_uuid())$$,'42501','conversation_forbidden','cross-organization assignee rejected');
select is(public.reassign_conversation_handoff('a0000000-0000-0000-0000-000000000001','b0000000-0000-4000-8000-000000000153','c0000000-0000-4000-8000-000000000151',2,'b0000000-0000-4000-8000-000000000152','f0000000-0000-4000-8000-000000000151')->>'status','STAFF_ACTIVE','manager recovers disabled claimant without resuming AI');
select is((select previous_actor_id from public.conversation_handoff_assignments where request_id='f0000000-0000-4000-8000-000000000151'),'b0000000-0000-4000-8000-000000000151'::uuid,'previous claimant preserved');
select is((select previous_claimed_at from public.conversation_handoff_assignments where request_id='f0000000-0000-4000-8000-000000000151'),'2026-01-01'::timestamptz,'previous claim time preserved');
select is(public.reassign_conversation_handoff('a0000000-0000-0000-0000-000000000001','b0000000-0000-4000-8000-000000000153','c0000000-0000-4000-8000-000000000151',2,'b0000000-0000-4000-8000-000000000152','f0000000-0000-4000-8000-000000000151')->>'revision','3','retry returns original revision');
select is((select count(*) from public.audit_events where idempotency_key='f0000000-0000-4000-8000-000000000151'),1::bigint,'reassignment audited once');
select throws_ok($$select public.reassign_conversation_handoff('a0000000-0000-0000-0000-000000000001','b0000000-0000-4000-8000-000000000153','c0000000-0000-4000-8000-000000000151',2,'b0000000-0000-4000-8000-000000000153',gen_random_uuid())$$,'40001','conversation_version_conflict','competing revision rejected');
reset role;
update public.staff_profiles set active=true where user_id='b0000000-0000-4000-8000-000000000151';
set local role service_role;
select throws_ok($$select public.transition_conversation_handoff('a0000000-0000-0000-0000-000000000001','b0000000-0000-4000-8000-000000000151','c0000000-0000-4000-8000-000000000151',3,'complete',gen_random_uuid())$$,'42501','conversation_forbidden','former claimant cannot complete after reactivation');
reset role;
create function pg_temp.reject_reassignment_audit() returns trigger language plpgsql as $$begin raise exception 'fixture_reassignment_audit_failure'; end$$;
create trigger reassignment_audit_fixture before insert on public.audit_events for each row execute function pg_temp.reject_reassignment_audit();
set local role service_role;
select throws_ok($$select public.reassign_conversation_handoff('a0000000-0000-0000-0000-000000000001','b0000000-0000-4000-8000-000000000153','c0000000-0000-4000-8000-000000000151',3,'b0000000-0000-4000-8000-000000000151',gen_random_uuid())$$,'P0001','fixture_reassignment_audit_failure','audit failure aborts reassignment');
select is((select claimed_by from public.conversation_handoffs where id='d0000000-0000-4000-8000-000000000151'),'b0000000-0000-4000-8000-000000000152'::uuid,'failed reassignment preserves claimant');
select is((select count(*) from public.conversation_handoff_assignments where handoff_id='d0000000-0000-4000-8000-000000000151'),1::bigint,'failed reassignment does not append history');
select * from finish();
rollback;
